import base64
import hashlib
import os
import secrets
import time
import urllib.parse
from typing import Dict, Optional

import requests


class Auth0PKCELoginFlow:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        scopes: Optional[list[str]] = None,
        audience: Optional[str] = None,
        timeout: int = 15,
    ) -> None:
        self.domain = (domain or os.environ["AUTH0_DOMAIN"]).strip()
        self.client_id = client_id or os.environ["AUTH0_CLIENT_ID"]
        self.redirect_uri = redirect_uri or os.environ["AUTH0_REDIRECT_URI"]
        self.scopes = scopes or ["openid", "profile", "email"]
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")
        self.timeout = timeout
        self.authorization_endpoint = f"https://{self.domain}/authorize"
        self.token_endpoint = f"https://{self.domain}/oauth/token"
        self.userinfo_endpoint = f"https://{self.domain}/userinfo"

    @staticmethod
    def _b64url(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

    @classmethod
    def generate_code_verifier(cls, length: int = 64) -> str:
        if not 43 <= length <= 128:
            raise ValueError("PKCE code_verifier length must be between 43 and 128 characters")
        verifier = cls._b64url(secrets.token_bytes(96))
        return verifier[:length]

    @classmethod
    def generate_code_challenge(cls, code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return cls._b64url(digest)

    @staticmethod
    def generate_state() -> str:
        return secrets.token_urlsafe(32)

    @staticmethod
    def generate_nonce() -> str:
        return secrets.token_urlsafe(32)

    def create_login_session(
        self,
        *,
        state: Optional[str] = None,
        nonce: Optional[str] = None,
        code_verifier: Optional[str] = None,
    ) -> Dict[str, str]:
        state = state or self.generate_state()
        nonce = nonce or self.generate_nonce()
        code_verifier = code_verifier or self.generate_code_verifier()
        code_challenge = self.generate_code_challenge(code_verifier)

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": " ".join(self.scopes),
            "state": state,
            "nonce": nonce,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.audience:
            params["audience"] = self.audience

        authorization_url = f"{self.authorization_endpoint}?{urllib.parse.urlencode(params)}"

        return {
            "authorization_url": authorization_url,
            "state": state,
            "nonce": nonce,
            "code_verifier": code_verifier,
            "created_at": str(int(time.time())),
        }

    @staticmethod
    def parse_callback_url(callback_url: str) -> Dict[str, Optional[str]]:
        parsed = urllib.parse.urlparse(callback_url)
        query = urllib.parse.parse_qs(parsed.query)
        return {
            "code": query.get("code", [None])[0],
            "state": query.get("state", [None])[0],
            "error": query.get("error", [None])[0],
            "error_description": query.get("error_description", [None])[0],
        }

    def exchange_code_for_tokens(
        self,
        *,
        authorization_code: str,
        code_verifier: str,
    ) -> Dict:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": authorization_code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }

        response = requests.post(
            self.token_endpoint,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=self.timeout,
        )
        response.raise_for_status()
        return response.json()

    def get_userinfo(self, access_token: str) -> Dict:
        response = requests.get(
            self.userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=self.timeout,
        )
        response.raise_for_status()
        return response.json()

    def complete_login(
        self,
        *,
        callback_url: str,
        expected_state: str,
        code_verifier: str,
        fetch_userinfo: bool = True,
    ) -> Dict:
        callback = self.parse_callback_url(callback_url)

        if callback["error"]:
            raise ValueError(
                f"Auth0 authorization error: {callback['error']}"
                + (f" - {callback['error_description']}" if callback["error_description"] else "")
            )

        if not callback["code"]:
            raise ValueError("Missing authorization code in callback URL")

        if callback["state"] != expected_state:
            raise ValueError("State mismatch detected")

        tokens = self.exchange_code_for_tokens(
            authorization_code=callback["code"],
            code_verifier=code_verifier,
        )

        result = {"tokens": tokens}

        if fetch_userinfo and "access_token" in tokens:
            result["userinfo"] = self.get_userinfo(tokens["access_token"])

        return result


def build_auth0_pkce_login_flow() -> Auth0PKCELoginFlow:
    return Auth0PKCELoginFlow()
